<script setup lang="ts">
export interface ImportSummary { read: number; importable: number; blocked: number; warnings: number }
export interface ImportAnomaly { line: number; name: string; blocking: boolean; messages: string[]; related: { id?: string; line?: number; organisation?: string; host?: string; source: string }[] }
defineProps<{ summary: ImportSummary; anomalies: ImportAnomaly[] }>();
</script>
<template><section aria-label="Rapport de contrôle"><h2 class="text-heading font-bold">Contrôle du fichier</h2><dl class="my-6 grid grid-cols-2 gap-4"><div><dt>Lignes lues</dt><dd class="text-heading font-bold">{{ summary.read }}</dd></div><div><dt>✓ Importables</dt><dd class="text-heading font-bold">{{ summary.importable }}</dd></div><div><dt>⛔ Bloquées</dt><dd class="text-heading font-bold">{{ summary.blocked }}</dd></div><div><dt>⚠ Homonymes</dt><dd class="text-heading font-bold">{{ summary.warnings }}</dd></div></dl><p class="mb-4">Les lignes bloquées ne seront pas importées. Un homonyme reste importable : demandez un second critère à l’accueil.</p><ul class="space-y-4"><li v-for="a in anomalies" :key="a.line" class="rounded border-2 p-4"><p class="font-bold">{{ a.blocking ? '⛔ Bloquée' : '⚠ Avertissement' }} · Ligne {{ a.line }} · {{ a.name || 'Nom manquant' }}</p><p v-for="message in a.messages" :key="message">{{ message }}</p><ul v-if="a.related.length" class="mt-2"><li v-for="(r,i) in a.related" :key="i">Fiche {{ r.line ? 'ligne '+r.line : r.id }} · {{ r.source }}<span v-if="r.organisation"> · Organisation : {{ r.organisation }}</span><span v-if="r.host"> · Hôte : {{ r.host }}</span></li></ul></li></ul><p v-if="!anomalies.length">✓ Aucune anomalie.</p></section></template>
